/bin/bash -lc "python - <<'PY'
palettes = {
'Light': ['FFFFFF','E8EDF5','17212B','475569','9F1239','166534','1D4ED8'],
'Dark': ['1C2530','29384A','F1F5F9','CBD5E1','FDA4AF','86EFAC','93C5FD'],
'Light increased': ['FFFFFF','E3E8EF','000000','1F2937','7F1231','14532D','153EAB'],
'Dark increased': ['080C10','162230','FFFFFF','E2E8F0','FFC0CB','B9F6CA','BFDBFE']}
def lum(h):
 c=[int(h[i:i+2],16)/255 for i in (0,2,4)]
 c=[v/12.92 if v<=.04045 else ((v+.055)/1.055)**2.4 for v in c]
 return sum(a*b for a,b in zip(c,[.2126,.7152,.0722]))
def contrast(a,b):
 x,y=sorted([lum(a),lum(b)])
 return (y+.05)/(x+.05)
for name, p in palettes.items():
 print(name)
 for role,fg in zip(['primary','secondary/unknown','disrupted','normal','accent'],p[2:]):
  print(role, '#'+fg, 'on #'+p[0],round(contrast(fg,p[0]),2),'on #'+p[1],round(contrast(fg,p[1]),2))
PY"

